package com.example.worldborderevent;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.minecraftforge.network.NetworkRegistry;import net.minecraftforge.network.PacketDistributor;import net.minecraftforge.network.simple.SimpleChannel;
public final class BorderNetwork{private static final String V="1";public static final SimpleChannel C=NetworkRegistry.ChannelBuilder.named(new ResourceLocation(WorldBorderEventMod.MODID,"main")).networkProtocolVersion(()->V).clientAcceptedVersions(V::equals).serverAcceptedVersions(V::equals).simpleChannel();private static boolean done;private BorderNetwork(){}public static void register(){if(done)return;done=true;C.messageBuilder(BorderRadiusPacket.class,0).encoder(BorderRadiusPacket::encode).decoder(BorderRadiusPacket::new).consumerMainThread(BorderRadiusPacket::handle).add();}public static void sendRadius(ServerPlayer p,double r){C.send(PacketDistributor.PLAYER.with(()->p),new BorderRadiusPacket(r));}}